g','g\'woon Extra jam ananas',NULL,NULL,NULL,NULL,'{{empty}}','/api/back-images/products/8710624291440-base.jpg',NULL,'Ananas, suiker, glucose-fructosestroop, voedingszuur: citroenzuur, geleermiddel: pectinen. Bereid met 50 g vruchten per 100 g.'),(15504,'8710624291402','450 g','g\'woon Extra jam abrikozen',NULL,NULL,NULL,NULL,'{{empty}}','/api/back-images/products/8710624291402-base.jpg',NULL,'Abrikozen, suiker, glucose-fructosestroop, voedingszuur: citroenzuur, geleermiddel: pectinen, antioxidant: ascorbinezuur.Bereid met 50 g vruchten per 100 g.'),(15505,'8710624219956','600 g','g\'woon Extra jam aardbei',NULL,NULL,NULL,NULL,'{{empty}}','/api/back-images/products/8710624219956-base.jpg',NULL,'Aardbeien, suiker, glucose-fructosestroop, voedingszuur: citroenzuur, geleermiddel: pectinen. Bereid met 50 g vruchten per 100 g.'),(15506,'8710624291426','450 g','g\'woon Extra jam aardbei',NULL,NULL,NULL,NULL,'{{empty}}','/api/back-images/products/8710624291426-base.jpg',NULL,'Aardbeien, suiker, glucose-fructosestroop, voedingszuur: citroenzuur, geleermiddel: pectinen. Bereid met 50 g\nvruchten per 100 g.'),(15507,'8710624307141','1 kg','g\'woon Espressobonen regular',NULL,NULL,NULL,NULL,'g\'woon heerlijke koffie\nVoor deze koffie gebruiken we een elegante melange van uitsluitend Arabica-bonen, waardoor een rijke zoete koffie ontstaat waarin ook de frisheid van rood fruit en de smaak van gebrande noten aanwezig is. Om g\'woon op ieder moment van de dag van te genieten. Deze espresso is een Slow Roast koffie. Dit betekent dat de koffie langzamer geroosterd wordt in authentieke branders. Doordat het proces van roosteren langer duurt, krijgen de aroma\'s en smaken die in de koffieboon zitten meer tijd om vrij te komen.','/api/back-images/products/8710624307141-base.jpg',NULL,'100% Koffie'),(15508,'8710624307226','500 g','g\'woon Espressobonen extra dark',NULL,NULL,NULL,NULL,'g\'woon heerlijke koffie\nVoor deze koffie gebruiken we een melange van Arabica-bonen, die voor een rijke, volle smaak zorgen, en Robusta-bonen, die zorgen voor een intense afdronk. Heerlijk als je g\'woon zin hebt in een intense espresso met een pittige smaak.\nDeze espresso is een Slow Roast koffie. Dit betekent dat de koffie langzamer geroosterd wordt in authentieke branders. Doordat het proces van roosteren langer duurt, krijgen de aroma\'s en smaken die in de koffieboon zitten meer tijd om vrij te komen.','/api/back-images/products/8710624307226-base.jpg',NULL,'100% Koffie'),(15509,'8710624307127','1 kg','g\'woon Espressobonen extra dark',NULL,NULL,NULL,NULL,'g\'woon heerlijke koffie\nVoor deze koffie gebruiken we een melange van Arabica-bonen, die voor een rijke, volle smaak zorgen, en Robusta-bonen, die zorgen voor een intense afdronk. Heerlijk als je g\'woon zin hebt in een intense espresso met een pittige smaak.\nDeze espresso is een Slow Roast koffie. Dit betekent dat de koffie langzamer geroosterd wordt in authentieke branders. Doordat het proces van roosteren langer duurt, krijgen de aroma\'s en smaken die in de koffieboon zitten meer tijd om vrij te komen.','/api/back-images/products/8710624307127-base.jpg',NULL,'100% Koffie'),(15510,'8710624307042','1 kg','g\'woon Espressobonen dark',NULL,NULL,NULL,NULL,'g\'woon heerlijke koffie\nVoor deze koffie gebruiken we een melange van Arabica-bonen, die zorgen voor een rijke smaak met tonen van cacao en noten, en Robusta-bonen, die de koffie extra pit geven. Voor alle momenten dat je g\'woon zin hebt in een krachtige espresso. Deze espresso is een Slow Roast koffie. Dit betekent dat de koffie langzamer geroosterd wordt in authentieke branders. Doordat het proces van roosteren langer duurt, krijgen de aroma\'s en smaken die in de koffieboon zitten meer tijd om vrij te komen.','/api/back-images/products/8710624307042-base.jpg',NULL,'100% Koffie'),(15511,'8710624307004','500 g','g\'woon Espresso original',NULL,NULL,NULL,NULL,'g\'woon heerlijke koffie\nVoor deze Espresso Original gebruiken we uitsluitend Arabica-bonen die medium gebrand worden, wat zorgt voor een verfijnde genuanceerde koffie. Espresso Original is een krachtige espresso met frisse en zoete smaaktonen van fruit, chocolade en hazelnoten. Heerlijk als je g\'woon zin hebt in een intense espresso.\nSlow roast betekent dat de koffie langzamer geroosterd wordt in authentieke branders. Doordat het proces van roosteren langer duurt, krijgen de aroma\'s en smaken die in de koffieboon zitten meer tijd om vrij te komen.','/api/back-images/products/8710624307004-base.jpg',NULL,'100% Koffie'),(15512,'8710624306984','500 g','g\'woon Espresso intens',NULL,NULL,NULL,NULL,'g\'woon heerlijke koffie\nEspresso Intens is een melange van Robusta- en Arabica-bonen. De Robusta-bonen zorgen voor de kracht en intensiteit en de Arabica-bonen zorgen voor de zoete nuances. Deze volle krachtige espresso heeft tonen van noten en zoethout. Voor alle momenten als je g\'woon zin hebt in een pittige espresso. Slow roast betekent dat de koffie langzamer geroosterd wordt in authentieke branders. Doordat het proces van roosteren langer duurt, krijgen de aroma\'s en smaken die in de koffieboon zitten meer tijd om vrij te komen.','/api/back-images/products/8710624306984-base.jpg',NULL,'100% Koffie'),(15513,'8710624280611','45 g','g\'woon Espresso',NULL,NULL,NULL,NULL,'G\'woon espresso is een krachtige koffie van speciaal geselecteerde bonen van hoge kwaliteit die zeer fijn zijn gemalen.\nIn handige sticks geschikt voor 1 koffiekopje om te genieten waar je maar wilt.','/api/back-images/products/8710624280611-base.jpg',NULL,'100% oploskoffie'),(15514,'8710624335335','300 ml','g\'woon Erwtensoep met rookworst',NULL,NULL,NULL,NULL,'g\'woon Erwtensoep beter leven','/api/back-images/products/8710624335335-base.jpg',NULL,'water, 20% erwten (spliterwten, doperwten, erwtenpuree), 11% rookworst (varkensvlees*, water, varkenscollageen*, varkenseiwit, zout, rookaroma, natuurlijk aroma, maltodextrine, rook), aardappel, wortel, prei, ui, BLADSELDERIJ, gemodificeerd maïszetmeel, zout, raapzaadolie, natuurlijke aroma\'s (SELDERIJ), plantaardig eiwithydrolysaat.* = Beter Leven keurmerk 1 ster'),(15515,'8710624313395','570 ml','g\'woon Erwtensoep met rookworst',NULL,NULL,NULL,NULL,'Aan deze erwtensoep zijn veel rookworst en spekjes toegevoegd. De erwten zijn een combinatie van doperwten en spliterwten. Spliterwten zijn doperwten die later worden geoogst, als de peul waar ze in groeien\ndroog is. Samen geven ze de vertrouwde smaak aan deze winterse soep, die natuurlijk ook g\'woon \'s zomers gegeten kan worden.','/api/back-images/products/8710624313395-base.jpg',NULL,'Water, 24% erwten (doperwten, spliterwten), 6,5% rookworst (74% varkensvlees¹, water, varkenscollageen¹, varkensvet¹, aardappelzetmeel, zout, varkenseiwit, conserveermiddel: E250, stabilisator: E450, kruiden, verdikkingsmiddel: E466, maltodextrine, specerijen, voedingszuur: E330/E575, antioxidant: E301, natuurlijk aroma, rook, rookaroma), 4% spekblokjes (80% varkensvlees¹, water, zout, antioxidant: E331/E392, conserveermiddel: E250), prei, aardappel, ui, wortel, KNOLSELDERIJ, gemodificeerd maïszetmeel, gistextract, kruiden (bevat SELDERIJ), zeezout, specerijen (bevat SELDERIJ), natuurlijk aroma, rookaroma. ¹ = Beter Leven keurmerk 1 ster'),(15516,'8710624335359','800 ml','g\'woon Erwtensoep met rookworst',NULL,NULL,NULL,NULL,'g\'woon Erwtensoep','/api/back-images/products/8710624335359-base.jpg',NULL,'water, 20% erwten (spliterwten, doperwten, erwtenpuree), 11% rookworst (varkensvlees*, water, varkenscollageen*, varkenseiwit, zout, rookaroma, natuurlijk aroma, maltodextrine, rook), aardappel, wortel, prei, ui, BLADSELDERIJ, gemodificeerd maïszetmeel, zout, raapzaadolie, natuurlijke aroma\'s (SELDERIJ), plantaardig eiwithydrolysaat.* = Beter Leven keurmerk 1 ster'),(15517,'8710624229108','240 g','g\'woon Engelse melange thee',NULL,NULL,NULL,NULL,'g\'woon engelse melange 60x4 gr','/api/back-images/products/8710624229108-base.jpg',NULL,'100% zwarte thee*. * Fairtrade i