ase.jpg',NULL,NULL),(22680,'8710624753887','250 g','Champignons roerbakgroenten',NULL,NULL,NULL,NULL,'Unbranded Champignons roerbakgroenten 250 GRM VERPAKT','/api/back-images/products/8710624753887-base.jpg',NULL,'43% Kastanjechampignons, 32% prei, 22% rode ui, peterselie.Dit product kan sporen van SELDERIJ bevatten.'),(22681,'8710624312985','400 g','Champignons kastanje',NULL,NULL,NULL,NULL,'Champignons kastanje','/api/back-images/products/8710624312985-base.jpg',NULL,'Kastanje champignons.'),(22682,'5413848659852','170 g','Champignon paté',NULL,NULL,NULL,NULL,'Champignon paté','/api/back-images/products/5413848659852-base.jpg',NULL,'25% varkenslever*, varkensvet*, MELK***, 13% varkensvlees*, 12% champignons, varkensbindweefsel*, SCHARRELEI, rijstbloem, zout, conserveermiddel: E250, voedingszuur: E262/E325; suiker, gebakken ui, specerijen (MOSTERD), natuurlijk aroma, antioxidant: E300/E330; dextrose. * = Beter Leven keurmerk 1 ster *** = Beter Leven keurmerk 3 sterren Kan sporen van NOTEN bevatten'),(22683,'8712846191508','150 g','Champignon mix',NULL,NULL,NULL,NULL,'Champignon mix','/api/back-images/products/8712846191508-base.jpg',NULL,'65% kastanje champignons, 15% witte beukenzwammen, 15% bosui, 5% bieslook'),(22684,'3287210000045','750 ml','Champagne Montaudon Brut',NULL,NULL,NULL,NULL,'Champagne Montaudon, established in Reims, has created powerful and fruit driven Pinot Noir led champagne from the Côte des Bar since its creation in 1891. The Brut Montaudon cuvee is an opulent, fruity and fleshy wine.','/api/back-images/products/3287210000045-base.jpg',NULL,'Nr.1 supermarkt champagne bij EditieNL'),(22685,'8715817008959','250 g','Chameur tros cherry tomaat',NULL,NULL,NULL,NULL,'Chameur tros cherry tomaat','/api/back-images/products/8715817008959-base.jpg',NULL,NULL),(22686,'4008429092770','150 g','Cesar hondenvoer nat classic met kip',NULL,NULL,NULL,NULL,'CESAR® Classic met Kip is bereid met de hoogste kwaliteit ingrediënten, zodat smaak en voedingswaarden op