land','16800','String'),(1194,'BrandAddress','Postbus 87,6880 AB,Velp','16541','String'),(1195,'ContactName','Coop Supermarkten','17720','String'),(1196,'ContactName','Coop Supermarkten','16541','String'),(1197,'Wettelijke Productnaam','gekruid, gemalen rundvlees','17720','String'),(1198,'Wettelijke Productnaam','gekruid, gemalen varkensvlees afgestopt in een varkensdarm','16541','String'),(1199,'Additieven','Verpakt onder beschermende atmosfeer','17720','String'),(1200,'Land van herkomst','Nederland','16541','String'),(1201,'Additieven','Verpakt onder beschermende atmosfeer','16541','String'),(1202,'BrandAddress','Postbus 87,6880 AB,Velp','22283','String'),(1203,'Land van Oorsprong','Nederland','16541','String'),(1204,'ContactName','Coop Supermarkten','22283','String'),(1205,'Wettelijke Productnaam','Gekookte worst, varkensvleesproduct','22283','String'),(1206,'Instructie voor gebruik','Bereidingsadvies rechtstreeks vanuit de diepvries: Magnetron: prik gaatjes in de folie. Verwarm product ca. 4 min. bij een vermogen van 500 W. (tijd kan per magnetron verschillen). Onmiddellijk na verwarmen omroeren. Au bain marie (pan): gesloten verpakking 24 min. in heet (niet kokend) water leggen. Omroeren voor gebruik. Pan: doe inhoud bakje in pan; met ca. 4 eetlepels water ca. 7 min. op middelmatige stand verwarmen. Regelmatig roeren. Het bakje is niet geschikt voor (hetelucht) oven of grill!','18851','String'),(1207,'Bewaaradvies','Bij -18°C ten minste houdbaar tot einde: zie zijkant bakje.\nDiepvries. Na ontdooiing niet opnieuw invriezen.','18851','String'),(1208,'Bewaaradvies','Na opening gekoeld bewahren. Niet invriezen.\nTen minste houdbaar tot: zie deksel.','23488','String'),(1209,'Bewaaradvies','Gekoeld bewaren (max. 7°C). Na openen beperkt houdbaar','19069','String'),(1210,'BrandAddress','Antwoordnummer 65013,5000 VH,Tilburg','18851','String'),(1211,'ContactName','Upfield Nederland B.V.','23488','String'),(1212,'BrandAddress','Antwoordnummer 3500,4140 VH,Beesd','19069',