g'),(38969,'BrandAddress','Industrieweg 161,3044 AS,Rotterdam','28104','String'),(38970,'ContactName','Verstegen Spices&Sauces B.V.','28104','String'),(38971,'Wettelijke Productnaam','MIX ORIËNTAALS','28104','String'),(38972,'Instructie voor gebruik','Bereidingswijze: \n\n\n\n\n\n\n\n\n\n\n\nDoe de inhoud van deze verpakking in een pan en verwarm het gedurende 7-10 minuten al roerend  op een laag vuur.\n\n\n\n\n\n\n\n\n\n\n\nIn de magnetron: Doe de inhoud van deze verpakking in een diep bord. Opwarmen op het maximale vermogen  3-4 minuten.','28105','String'),(38973,'Land van Oorsprong','Nederland','28104','String'),(38974,'Bewaaradvies','Koel en droog bewaren. Na opwarmen niet opnieuw bewaren','28105','String'),(38975,'Bewaaradvies','Bij kamertemperatuur (15-25 graden Celsius) op een droge en donkere plaats (in de originele verpakking) bewaren. Buiten bereik van jonge kinderen bewaren.','28106','String'),(38976,'BrandAddress','Postbus 56,1420 AB,Uithoorn','28105','String'),(38977,'BrandAddress','Postbus 6612,3002 AP,Rotterdam','28106','String'),(38978,'ContactName','Engel Foreign Food','28105','String'),(38979,'ContactName','Omega Pharma','28106','String'),(38980,'Wettelijke Productnaam','Soep van runderpens en tomaten','28105','String'),(38981,'Wettelijke Productnaam','Actifit 65+','28106','String'),(38982,'Additieven','Een gezonde levensstijl is belangrijk, evenals een gevarieerde, evenwichtige voeding, waarvoor voedingssupplementen geen vervanging zijn.','28106','String'),(38983,'Bewaaradvies','Koel en donker. Na openen houdbaar in de koelkast (4-7°).\n\nTenminste houdbaar tot: zie bovenzijde.','28107','String'),(38984,'Bewaaradvies','Koel, droog en donker bewaren. Na openen beperkt houdbaar in de koelkast (max. 7°C)','28108','String'),(38985,'BrandAddress','Luchtenburgseweg 2,4858 RJ,Ulvenhout','28107','String'),(38986,'ContactName','Engel Foreign Food','28108','String'),(38987,'ContactName','De Smaakspecialist','28107','String'),(38988,'Wettelijke Productnaam',